window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["information-theory"]={"title":"信息论与熵：从概率到编码代价","subtitle":"先分清真实分布 P 与模型分布 Q，再从自信息、熵逐步推出交叉熵、KL 散度和困惑度。","thesis":"信息论把“模型给真实事件多大概率”转换成可累加的编码代价：熵是知道真实分布时的最低平均代价，交叉熵是改用模型分布后的平均代价，两者之差是 KL；但这些量只衡量概率匹配，<b>不直接代表事实性、语义价值或通用智能</b>。","quality":{"contractVersion":2,"examples":[{"section":8,"evidence":{"setup":"真实天气分布 P=(1/2,1/4,1/4)","rule":"先用 P 自己的码长求平均","steps":"事件仍按 P 出现，所以把 Q 码长按 P 加权相加","interpretation":"概率放错位置就会增加平均损失"}}],"termReviews":[{"section":9,"reviewedAt":"2026-07-26","terms":[{"name":"似然","meaning":"模型为已观察序列分配的整体概率","purpose":"比较模型对已观察文本的解释程度","definitionEvidence":"似然 在这里表示模型给整句真实 token 序列分配了多大概率","purposeEvidence":"用来比较模型对已观察文本的解释程度"},{"name":"对数似然","meaning":"逐步概率乘积取对数后得到的和","purpose":"把连乘改写成便于稳定计算的加法","definitionEvidence":"对数似然 把逐步概率的乘法变成对数之和","purposeEvidence":"便于稳定计算"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"概率分布为所有可能事件分配非负且总和为一的概率。","evidence":"概率分布会给每个事件分配一个不小于 0 的数"},"problem":{"answer":"本节建立后续信息量公式共同使用的事件、分布、对数与期望。","evidence":"后面所有公式究竟在对什么对象做计算"},"inputOutput":{"answer":"输入是真实分布 P、模型分布 Q 与事件 x，输出是平均预测或编码代价。","evidence":"平均要付出多大代价"},"mechanism":{"answer":"对数把独立事件的概率乘法变成信息量加法，期望再按 P 加权平均。","evidence":"用事件真实出现的概率作权重求加权平均"},"interpretation":{"answer":"下标 P 表示事件按谁出现，公式中的 Q 表示模型给真实事件的概率。","evidence":"看到下标 P，先问"},"boundary":{"answer":"现实中的真实分布 P 通常不可直接知道，只能用有限样本估计。","evidence":"现实中 P 通常未知"}},{"section":2,"definition":{"answer":"自信息是事件发生时消除的不确定性，等于其概率的负对数。","evidence":"I P (x)=−log₂P(x)"},"problem":{"answer":"它量化一次具体结果究竟有多罕见、多令人意外。","evidence":"一次结果有多意外"},"inputOutput":{"answer":"输入事件概率 P(x)，输出以 bit 表示的单次信息量。","evidence":"概率减半，自信息增加 1 bit"},"mechanism":{"answer":"对事件概率取以二为底的负对数，概率越小结果越大。","evidence":"自信息依次是 1、2、3 bit"},"interpretation":{"answer":"零 bit 表示结果完全确定，数值越大表示事件越意外。","evidence":"观察到它没有消除任何不确定性"},"boundary":{"answer":"高自信息只表示罕见，不代表该事件重要或对任务有用。","evidence":"不表示事件的重要性"}},{"section":3,"definition":{"answer":"熵是按照真实分布，对所有事件自信息求出的加权平均。","evidence":"熵就是按真实频率 P 对每个事件的自信息求平均"},"problem":{"answer":"它概括整个真实分布平均有多不确定、多难预测。","evidence":"怎样概括整个分布平均有多难预测"},"inputOutput":{"answer":"输入完整真实分布 P，输出每次事件的平均信息量或理想编码代价。","evidence":"H(P)=1/2×1+1/4×2+1/4×2=1.5"},"mechanism":{"answer":"先计算各事件自信息，再用各自真实概率加权求和。","evidence":"三个事件的信息量是 1、2、2 bit"},"interpretation":{"answer":"均匀分布熵最大，确定分布熵为零，表示平均不确定性的两个端点。","evidence":"均匀分布的熵最大"},"boundary":{"answer":"理想长期平均码长不等于单个现实码字或文件的实际占用。","evidence":"单个符号的实际码字通常受整数长度"}},{"section":4,"definition":{"answer":"交叉熵是数据按 P 出现、模型按 Q 报概率时的平均对数损失。","evidence":"H(P,Q)=E x∼P [−log₂Q(x)]"},"problem":{"answer":"它衡量模型分布 Q 预测真实分布 P 时长期平均要付出的代价。","evidence":"平均损失究竟怎样计算"},"inputOutput":{"answer":"输入真实分布 P 和模型分布 Q，输出以 bit 计的平均损失。","evidence":"P 决定哪些事件多常出现"},"mechanism":{"answer":"对真实事件的负对数概率求单次损失，再用 P 作权重平均。","evidence":"计算 −log₂Q(x)"},"interpretation":{"answer":"Q 给真实事件的概率越大损失越小，漏掉真实事件则代价很高。","evidence":"Q 给真实事件的概率越大，损失越小"},"boundary":{"answer":"只有 Q 与 P 相同的时候，交叉熵才退化为真实分布自身的熵。","evidence":"若恰好 Q=P"}},{"section":5,"definition":{"answer":"KL 散度是使用模型分布 Q 相对使用真实分布 P 多出的平均对数代价。","evidence":"每次事件平均多付出的 bit 数"},"problem":{"answer":"它隔离交叉熵中由模型分布与真实分布失配造成的额外代价。","evidence":"交叉熵比熵多出的代价"},"inputOutput":{"answer":"输入有方向的 P 与 Q，输出非负的平均额外 bit 数。","evidence":"H(P,Q)−H(P)"},"mechanism":{"answer":"用交叉熵减去真实分布自身的熵，等价于对概率比的对数按 P 平均。","evidence":"把前者从后者中减掉"},"interpretation":{"answer":"KL 为零表示 Q 在 P 会发生的事件上与 P 一致。","evidence":"完全一致时为 0"},"boundary":{"answer":"KL 有方向且可为无穷，训练集交叉熵下降也不保证真实 KL 下降。","evidence":"训练损失下降不保证未知数据上的真实 KL"}},{"section":6,"definition":{"answer":"欧氏距离是概率坐标差的几何长度，KL 是有方向的平均对数代价。","evidence":"欧氏距离把两个概率分布当作普通向量"},"problem":{"answer":"本节解释为何普通几何距离不能替代 KL 表达预测或编码后悔。","evidence":"为什么不直接计算两点之间的直线距离"},"inputOutput":{"answer":"两者都输入概率分布 P、Q，但分别输出几何尺度和 bit 代价。","evidence":"本页使用 bit/事件"},"mechanism":{"answer":"欧氏距离平方求和再开根号；KL 则计算概率比例的加权对数。","evidence":"衡量坐标差的几何长度"},"interpretation":{"answer":"欧氏距离回答坐标相差多远，KL 回答用 Q 预测 P 多付多少。","evidence":"它们回答的不是同一个问题"},"boundary":{"answer":"KL 不对称且不满足三角不等式，所以不是严格数学距离。","evidence":"严格说它是“散度”而不是数学上的距离"}},{"section":7,"definition":{"answer":"困惑度是平均对数损失指数化后得到的熵等效分支数。","evidence":"更准确的名称是"},"problem":{"answer":"它把抽象的平均 bit 或 nat 损失转换成较直观的等效选择数量。","evidence":"怎样换成较直观的等效选择数"},"inputOutput":{"answer":"输入平均 token 交叉熵，输出正数形式的等效分支数。","evidence":"PPL=2 H(P,Q)"},"mechanism":{"answer":"bit 损失使用二为底指数，nat 损失使用自然指数。","evidence":"若训练损失使用自然对数"},"interpretation":{"answer":"数值越低表示模型平均给实际 token 的概率越高。","evidence":"PPL 越低只说明模型给实际 token 的平均概率更高"},"boundary":{"answer":"困惑度不等于词表大小，也不能跨不同 tokenizer 直接比较。","evidence":"不能跨 tokenizer 直接比较"}},{"section":8,"definition":{"answer":"该例把熵、交叉熵、KL 与困惑度连接成一次完整数值推导。","evidence":"从 P、Q 一直算到困惑度"},"problem":{"answer":"它解决只会背公式却不知道每一步由谁加权、为何计算的问题。","evidence":"每一步怎样对应前面的定义"},"inputOutput":{"answer":"输入天气分布 P 与模型分布 Q，输出四个相互关联的信息量指标。","evidence":"真实天气分布 P=(1/2,1/4,1/4)"},"mechanism":{"answer":"先算 P 的熵，再按 P 加权 Q 的码长，二者相减并指数化。","evidence":"先用 P 自己的码长求平均"},"interpretation":{"answer":"Q 把概率放错事件会增加平均损失，低估真实事件尤其昂贵。","evidence":"概率放错位置就会增加平均损失"},"boundary":{"answer":"若 Q 给 P 可能发生的事件零概率，对数损失和正向 KL 都会无穷大。","evidence":"正向 KL 都变为正无穷"}},{"section":9,"definition":{"answer":"经验交叉熵是有限样本上逐 token 负对数概率的平均。","evidence":"就是常见的经验交叉熵"},"problem":{"answer":"它说明不知道真实分布 P 时，训练程序怎样得到可计算损失。","evidence":"训练程序又是怎样得到交叉熵损失"},"inputOutput":{"answer":"输入真实 token 序列和模型条件概率，输出序列或批次平均损失。","evidence":"每一步给真实下一个 token 概率"},"mechanism":{"answer":"对逐步条件概率取对数求和、加负号，再按 token 和批次平均。","evidence":"把逐步概率的乘法变成对数之和"},"interpretation":{"answer":"验证或测试损失用于估计新数据表现，但仍受有限抽样误差影响。","evidence":"用于估计新数据表现，仍有抽样误差"},"boundary":{"answer":"训练损失下降只说明拟合当前训练样本，不能单独证明通用能力改善。","evidence":"只说明模型更适合当前训练样本"}}],"formulas":[{"id":"self-information","section":2,"formulaIndex":1,"symbols":[{"name":"I","meaning":"事件发生时获得的自信息","evidence":"自信息：一次结果有多意外"},{"name":"P","meaning":"数据的真实分布","evidence":"真实分布或数据分布","section":1},{"name":"x","meaning":"实际发生的事件","evidence":"实际发生的一个事件","section":1}]},{"id":"entropy","section":3,"formulaIndex":1,"symbols":[{"name":"H","meaning":"真实分布的平均自信息，即熵","evidence":"熵就是按真实频率 P 对每个事件的自信息求平均"},{"name":"P","meaning":"数据的真实分布","evidence":"真实分布或数据分布","section":1},{"name":"x","meaning":"实际发生的事件","evidence":"实际发生的一个事件","section":1},{"name":"E","meaning":"按真实分布加权求平均","evidence":"按 P 取期望","section":1}]},{"id":"event-log-loss","section":4,"formulaIndex":1,"symbols":[{"name":"Q","meaning":"模型给出的预测分布","evidence":"模型分布或预测分布","section":1},{"name":"x","meaning":"当前实际发生的事件","evidence":"实际发生的一个事件","section":1}]},{"id":"cross-entropy","section":4,"formulaIndex":2,"symbols":[{"name":"H","meaning":"使用模型分布编码真实事件的平均代价","evidence":"得到交叉熵"},{"name":"P","meaning":"决定事件出现频率的真实分布","evidence":"P 决定哪些事件多常出现"},{"name":"Q","meaning":"决定预测概率与码长的模型分布","evidence":"Q 决定模型为这些事件付出多少损失"},{"name":"E","meaning":"按真实分布加权求平均","evidence":"长期平均时必须用 P 作权重"},{"name":"x","meaning":"当前实际发生的事件","evidence":"事件 x 真正发生后"}]},{"id":"kl-from-cross-entropy","section":5,"formulaIndex":1,"symbols":[{"name":"H","meaning":"熵或交叉熵","evidence":"平均理想码长是 H(P)"},{"name":"P","meaning":"数据真实分布","evidence":"知道真实分布 P"},{"name":"Q","meaning":"用于预测或编码的模型分布","evidence":"改用模型分布 Q"},{"name":"D","meaning":"KL 散度记号","evidence":"可以理解为：数据按 P 产生"},{"name":"KL","meaning":"模型相对真实分布多付的平均编码代价","evidence":"每次事件平均多付出的 bit 数"},{"name":"x","meaning":"事件索引","evidence":"P 可能出现的事件"}]},{"id":"cross-entropy-decomposition","section":5,"formulaIndex":2,"symbols":[{"name":"H","meaning":"熵与交叉熵","evidence":"平均理想码长是 H(P)"},{"name":"P","meaning":"数据真实分布","evidence":"知道真实分布 P"},{"name":"Q","meaning":"模型分布","evidence":"改用模型分布 Q"},{"name":"D","meaning":"KL 散度记号","evidence":"可以理解为：数据按 P 产生"},{"name":"KL","meaning":"额外平均编码代价","evidence":"每次事件平均多付出的 bit 数"}]},{"id":"euclidean-distance","section":6,"formulaIndex":1,"symbols":[{"name":"d","meaning":"两个概率向量的欧氏距离","evidence":"欧氏距离把两个概率分布当作普通向量"},{"name":"P","meaning":"第一个概率分布","evidence":"两个概率分布当作普通向量"},{"name":"Q","meaning":"第二个概率分布","evidence":"两个概率分布当作普通向量"},{"name":"x","meaning":"概率向量的事件坐标","evidence":"概率坐标相差多远"}]},{"id":"perplexity-from-bits","section":7,"formulaIndex":1,"symbols":[{"name":"PPL","meaning":"熵等效分支数，即困惑度","evidence":"熵等效分支数"},{"name":"H","meaning":"以 bit 每 token 计量的平均交叉熵","evidence":"平均交叉熵是 2 bit/token"},{"name":"P","meaning":"真实分布","evidence":"真实分布或数据分布","section":1},{"name":"Q","meaning":"模型预测分布","evidence":"模型分布或预测分布","section":1}]},{"id":"language-model-nll","section":9,"formulaIndex":1,"symbols":[{"name":"NLL","meaning":"整句负对数似然","evidence":"整句负对数似然为"},{"name":"Q","meaning":"语言模型给真实下一个 token 的概率","evidence":"给真实下一个 token 概率"},{"name":"x","meaning":"序列中的 token","evidence":"把一句话分成"},{"name":"t","meaning":"token 的预测位置","evidence":"在每一步"}]}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分事件、概率分布 P 与模型分布 Q；从自信息和熵推导交叉熵与 KL；比较 KL 与欧氏距离的用途；解释困惑度及其比较边界。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>先把 P、Q、对数和期望说清楚<span class=\"dd-badge math\">起点</span></h2><p class=\"dd-lead\">后面所有公式究竟在对什么对象做计算？</p>\n        <p>设一次试验可能产生有限个事件，例如天气集合 <code>Ω={晴, 雨, 雪}</code>。概率分布会给每个事件分配一个不小于 0 的数，而且所有概率之和为 1。</p>\n        <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>符号</th><th>本页含义</th><th>天气例子</th></tr></thead><tbody>\n        <tr><td><code>x</code></td><td>实际发生的一个事件</td><td>今天实际下雪</td></tr>\n        <tr><td><code>P(x)</code></td><td>数据真正按什么频率产生；称为真实分布或数据分布</td><td>长期有 25% 的天会下雪</td></tr>\n        <tr><td><code>Q(x)</code></td><td>模型认为事件会发生的概率；称为模型分布或预测分布</td><td>模型只给下雪 12.5% 概率</td></tr>\n        </tbody></table></div>\n        <p>教学例子会直接给出 P，现实中 P 通常未知，只能用样本频率近似。Q 则由模型给出。我们关心的是：数据仍按 P 出现时，如果根据 Q 做预测或设计编码，平均要付出多大代价。</p>\n<p><b>为什么信息量要用对数？</b>我们希望越罕见的事件带来的信息越多；同时，两个独立事件一起发生时，概率相乘，而它们带来的信息应当相加。对数正好把乘法变成加法：<code>log₂(ab)=log₂a+log₂b</code>。由于概率不超过 1，<code>log₂P(x)</code> 不大于 0，所以再加一个负号，得到非负的信息量 <code>I(x)=-log₂P(x)</code>。</p>\n<p><b>为什么选 <code>log₂</code>？</b>底数 2 能把信息量解释成“需要多少次理想的二选一判断”。若一个事件的概率是 <code>1/2</code>，区分它相当于回答 1 个答案各占一半的是非问题，因此信息量是 <code>-log₂(1/2)=1 bit</code>；概率是 <code>1/4</code> 时，需要 2 次这样的判断，信息量是 <code>2 bits</code>；概率是 <code>1/8</code> 时则是 <code>3 bits</code>。</p>\n<div class=\"dd-note key\"><b>bit 是什么：</b>bit 是信息量的单位，表示一次理想且均衡的二元区分所提供的信息。这里说“2 bits”是在描述理想信息量或理想编码长度，不等于现实文件一定恰好占 2 个物理存储位。若改用自然对数 <code>ln</code>，单位会变成 nat；数值只按固定比例缩放，不会改变事件之间的信息量大小关系。本页采用 <code>log₂</code>，是因为二元判断和二进制编码更直观。</div>\n<p>所谓“按 P 取期望”，就是用事件真实出现的概率作权重求加权平均：<code>E<sub>P</sub>[f(x)]=ΣₓP(x)f(x)</code>。</p>\n        <div class=\"dd-note key\"><b>阅读约定：</b>看到下标 P，先问“事件实际按谁出现”；看到公式里的 Q，先问“模型给这个真实事件多少概率”。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>自信息：一次结果有多意外<span class=\"dd-badge math\">自信息</span></h2><p class=\"dd-lead\">为什么概率越小的事件一旦发生，带来的信息越多？</p>\n        <div class=\"dd-formula\">I<sub>P</sub>(x)=−log₂P(x)</div>\n        <p>如果某事件必然发生，<code>P(x)=1</code>，那么 <code>I(x)=0</code> bit：观察到它没有消除任何不确定性。若概率减半，自信息增加 1 bit；概率从 <code>1/2</code>、<code>1/4</code> 到 <code>1/8</code>，自信息依次是 1、2、3 bit。</p>\n        <p>这里的信息量只表示“意外程度”，不表示事件的重要性。罕见的传感器噪声可以有很高自信息，却未必对任务有价值。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>熵：真实分布自身的平均不确定性<span class=\"dd-badge math\">熵</span></h2><p class=\"dd-lead\">单次事件的信息量不同，怎样概括整个分布平均有多难预测？</p>\n        <div class=\"dd-formula\">H(P)=E<sub>x∼P</sub>[−log₂P(x)]=−ΣₓP(x)log₂P(x)</div>\n        <p>熵就是按真实频率 P 对每个事件的自信息求平均。对于 <code>P=(1/2,1/4,1/4)</code>，三个事件的信息量是 1、2、2 bit，所以 <code>H(P)=1/2×1+1/4×2+1/4×2=1.5</code> bit/次。</p>\n        <p>在 n 个可能结果上，均匀分布的熵最大，为 <code>log₂n</code>；确定分布的熵为 0。这里的“最低平均编码代价”是理想化、长期平均的无损编码结论：单个符号的实际码字通常受整数长度、编码器和头部开销影响。</p>\n        <div class=\"dd-note warn\"><b>不要混淆：</b>某次罕见事件自信息很大，不代表整个分布的熵一定高；熵也不评价某条回答是否正确。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>交叉熵：用 Q 为按 P 出现的数据付费<span class=\"dd-badge math\">交叉熵</span></h2><p class=\"dd-lead\">真实事件按 P 出现，模型却按 Q 分配概率时，平均损失究竟怎样计算？</p>\n        <p>模型事先不知道下一次会出现什么，只能提交一整组预测概率 Q。事件 x 真正发生后，我们只检查模型给这个事件的概率 <code>Q(x)</code>，并把它转换为对数损失或理想码长：</p>\n        <div class=\"dd-formula\">模型对事件 x 的损失 = −log₂Q(x)</div>\n        <p>Q 给真实事件的概率越大，损失越小；如果 Q 很自信地漏掉真实事件，损失会非常大。由于事件实际仍按 P 出现，长期平均时必须用 P 作权重：</p>\n        <div class=\"dd-formula\">H(P,Q)=E<sub>x∼P</sub>[−log₂Q(x)]=−ΣₓP(x)log₂Q(x)</div>\n        <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>步骤</th><th>谁决定</th><th>要做的事</th></tr></thead><tbody>\n        <tr><td>1. 事件出现</td><td>真实分布 P</td><td>决定晴、雨、雪各出现多频繁</td></tr>\n        <tr><td>2. 模型报概率</td><td>模型分布 Q</td><td>给每个可能事件分配预测概率</td></tr>\n        <tr><td>3. 计算单次损失</td><td>实际事件对应的 Q(x)</td><td>计算 <code>−log₂Q(x)</code></td></tr>\n        <tr><td>4. 求长期平均</td><td>P 作权重</td><td>得到交叉熵 <code>H(P,Q)</code></td></tr>\n        </tbody></table></div>\n        <p>名称里的“交叉”来自两个分布各司其职：P 决定哪些事件多常出现，Q 决定模型为这些事件付出多少损失。若恰好 <code>Q=P</code>，交叉熵就退化为熵。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>KL 散度：交叉熵比熵多出的代价<span class=\"dd-badge math\">KL</span></h2><p class=\"dd-lead\">KL 不需要凭空记忆，它可以从“用了错误的 Q 多花多少”直接推出。</p>\n        <p>知道真实分布 P 时，平均理想码长是 <code>H(P)</code>；改用模型分布 Q 后，平均代价是 <code>H(P,Q)</code>。把前者从后者中减掉：</p>\n        <div class=\"dd-formula\">H(P,Q)−H(P)=ΣₓP(x)log₂[P(x)/Q(x)]=D<sub>KL</sub>(P∥Q)</div>\n        <p>所以 <code>D<sub>KL</sub>(P∥Q)</code> 可以理解为：数据按 P 产生，却使用 Q 预测或编码时，每次事件平均多付出的 bit 数。由此得到：</p>\n        <div class=\"dd-formula\">H(P,Q)=H(P)+D<sub>KL</sub>(P∥Q)</div>\n        <ul>\n          <li>KL 总是不小于 0；当 Q 与 P 在 P 可能出现的事件上完全一致时为 0。</li>\n          <li>方向不能交换：<code>KL(P∥Q)</code> 用 P 加权，重点惩罚 Q 漏掉真实会发生的事件。</li>\n          <li>若 <code>P(x)&gt;0</code> 而 <code>Q(x)=0</code>，该项为正无穷，正向 KL 也为正无穷。</li>\n        </ul>\n        <p>等式中的“最小化交叉熵等价于最小化 KL”针对同一个固定真实分布 P 的总体量成立。训练集上的平均损失只是总体交叉熵的经验估计；训练损失下降不保证未知数据上的真实 KL 一定下降。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>KL 与欧氏距离回答不同问题<span class=\"dd-badge math\">距离比较</span></h2><p class=\"dd-lead\">既然 P 和 Q 都能写成概率向量，为什么不直接计算两点之间的直线距离？</p>\n        <p>欧氏距离把两个概率分布当作普通向量：</p>\n        <div class=\"dd-formula\" data-formula-id=\"euclidean-distance\" data-display=\"mathml\"><math display=\"block\" aria-label=\"P 与 Q 的欧氏距离等于各事件概率之差的平方和再开平方\"><mrow><msub><mi>d</mi><mn>2</mn></msub><mo>(</mo><mi>P</mi><mo>,</mo><mi>Q</mi><mo>)</mo><mo>=</mo><msqrt><mrow><munder><mo>∑</mo><mi>x</mi></munder><msup><mrow><mo>(</mo><mi>P</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>−</mo><mi>Q</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>)</mo></mrow><mn>2</mn></msup></mrow></msqrt></mrow></math></div>\n        <p>它衡量坐标差的几何长度，具有对称性：<code>d₂(P,Q)=d₂(Q,P)</code>，并满足三角不等式。KL 衡量的则是概率比例造成的平均对数代价，通常不对称，也不满足三角不等式，因此严格说它是“散度”而不是数学上的距离。</p>\n        <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>问题</th><th>欧氏距离</th><th>KL(P∥Q)</th></tr></thead><tbody>\n        <tr><td>关注什么</td><td>概率坐标相差多远</td><td>Q 预测 P 时多付多少对数代价</td></tr>\n        <tr><td>是否对称</td><td>是</td><td>否</td></tr>\n        <tr><td>Q 漏掉 P 的可能事件</td><td>仍是有限数</td><td>若 Q(x)=0，则为正无穷</td></tr>\n        <tr><td>单位</td><td>概率向量的几何尺度</td><td>本页使用 bit/事件</td></tr>\n        </tbody></table></div>\n        <p>例如 <code>P=(0.5,0.25,0.25)</code>、<code>Q=(0.5,0.375,0.125)</code> 的欧氏距离约为 0.177，而正向 KL 约为 0.104 bit。两个数不能互相换算：它们回答的不是同一个问题。欧氏距离并非“错误”，只是不表达编码后悔或对数预测损失。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>困惑度：把平均对数损失还原到概率尺度<span class=\"dd-badge math\">困惑度</span></h2><p class=\"dd-lead\">平均损失是 1.6 bit/token 很抽象，怎样换成较直观的等效选择数？</p>\n        <div class=\"dd-formula\">PPL=2<sup>H(P,Q)</sup>　（损失单位为 bit/token）</div>\n        <p>如果平均交叉熵是 2 bit/token，那么 <code>PPL=2²=4</code>。它表示模型的平均不确定性，与“每一步面对 4 个等概率候选”的情形相当，因此更准确的名称是<b>熵等效分支数</b>。</p>\n        <p>困惑度不是词表大小，也不表示模型真的每一步只考虑固定数量的词。PPL 越低只说明模型给实际 token 的平均概率更高；它不自动证明事实性、推理能力或安全性更好。</p>\n        <p>这里提前用到 token：可以暂时把 token 理解为模型逐步预测的文本单位，正式分词机制将在 2.8 学习。不同 tokenizer 会改变预测单位和序列长度，所以 token 级 PPL 通常不能跨 tokenizer 直接比较。跨分词器时可考虑统一语料上的 bits-per-byte 或 bits-per-character。</p>\n        <div class=\"dd-note key\"><b>底数必须匹配：</b>若训练损失使用自然对数，单位是 nat/token，应使用 <code>PPL=exp(loss)</code>；若使用 <code>log₂</code>，才使用 <code>2<sup>loss</sup></code>。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>三符号例子：从 P、Q 一直算到困惑度<span class=\"dd-badge math\">完整手算</span></h2><p class=\"dd-lead\">真实天气分布 P=(1/2,1/4,1/4)，模型 Q=(1/2,3/8,1/8) 时，每一步怎样对应前面的定义？</p>\n        <figure class=\"dd-fig\"><svg viewBox=\"0 0 680 245\" role=\"img\" aria-label=\"真实分布 P 与模型分布 Q 的编码长度、交叉熵和 KL 额外代价\"><defs><marker id=\"it1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"170\" height=\"152\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"103\" y=\"59\" text-anchor=\"middle\" class=\"svg-t\">真实分布 P</text><text x=\"38\" y=\"88\" class=\"svg-t\" font-size=\"10\">晴：p=1/2 → 1 bit</text><text x=\"38\" y=\"113\" class=\"svg-t\" font-size=\"10\">雨：p=1/4 → 2 bit</text><text x=\"38\" y=\"138\" class=\"svg-t\" font-size=\"10\">雪：p=1/4 → 2 bit</text><text x=\"38\" y=\"167\" class=\"svg-t\" font-size=\"10\">H(P)=1/2×1+1/4×2+1/4×2</text><text x=\"103\" y=\"181\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">= 1.5 bit</text><path d=\"M188,110 L248,110\" stroke=\"#6b7484\" marker-end=\"url(#it1)\"/><rect x=\"250\" y=\"35\" width=\"190\" height=\"152\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"345\" y=\"59\" text-anchor=\"middle\" class=\"svg-t\">模型编码 Q</text><text x=\"270\" y=\"88\" class=\"svg-t\" font-size=\"10\">晴：q=1/2 → 1 bit</text><text x=\"270\" y=\"113\" class=\"svg-t\" font-size=\"10\">雨：q=3/8 → 1.415 bit</text><text x=\"270\" y=\"138\" class=\"svg-t\" font-size=\"10\">雪：q=1/8 → 3 bit</text><text x=\"270\" y=\"163\" class=\"svg-t\" font-size=\"10\">H(P,Q)=0.5+0.3538+0.75</text><text x=\"345\" y=\"181\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">≈ 1.6038 bit</text><path d=\"M440,110 L500,110\" stroke=\"#6b7484\" marker-end=\"url(#it1)\"/><rect x=\"502\" y=\"57\" width=\"160\" height=\"108\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"582\" y=\"82\" text-anchor=\"middle\" class=\"svg-t\">额外编码代价</text><text x=\"582\" y=\"108\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">Dₖₗ(P||Q)</text><text x=\"582\" y=\"131\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">= H(P,Q)−H(P)</text><text x=\"582\" y=\"151\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">≈ 0.1038 bit / 符号</text><text x=\"340\" y=\"224\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">P 决定事件出现频率；Q 决定模型给它分配的理想码长。Q 越低估真实事件，事件发生时损失越大。</text></svg><figcaption>图 1　P 决定“哪些事件多常进入平均”；Q 决定“模型为已发生事件付出多少损失”。</figcaption></figure>\n        <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>事件 x</th><th>真实频率 P(x)</th><th>最优码长 −log₂P(x)</th><th>模型概率 Q(x)</th><th>模型码长 −log₂Q(x)</th><th>交叉熵中的贡献 P(x)[−log₂Q(x)]</th></tr></thead><tbody>\n        <tr><td>晴</td><td>0.5</td><td>1</td><td>0.5</td><td>1</td><td>0.5000</td></tr>\n        <tr><td>雨</td><td>0.25</td><td>2</td><td>0.375</td><td>1.415</td><td>0.3538</td></tr>\n        <tr><td>雪</td><td>0.25</td><td>2</td><td>0.125</td><td>3</td><td>0.7500</td></tr>\n        </tbody></table></div>\n        <ol class=\"dd-steps\">\n          <li>先用 P 自己的码长求平均：<code>H(P)=0.5×1+0.25×2+0.25×2=1.5</code> bit。</li>\n          <li>再看 Q 为实际事件分配的码长。以雪为例，Q 只给 0.125，所以雪发生时损失是 <code>−log₂0.125=3</code> bit。</li>\n          <li>事件仍按 P 出现，所以把 Q 码长按 P 加权相加：<code>H(P,Q)=0.5000+0.3538+0.7500≈1.6038</code> bit。</li>\n          <li>多付出的代价是 <code>KL(P∥Q)=1.6038−1.5≈0.1038</code> bit/次。</li>\n          <li>把平均损失指数化：<code>PPL=2<sup>1.6038</sup>≈3.04</code>，即约 3.04 个等概率候选的同等不确定性。</li>\n        </ol>\n        <p>Q 对雨分得过多、对雪分得过少。总概率虽然仍是 1，但概率放错位置就会增加平均损失。若 Q 把雪设为 0，雪一旦发生便得到无限对数损失，交叉熵和正向 KL 都变为正无穷。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>语言模型损失：样本平均不等于真实分布<span class=\"dd-badge eng\">语言模型</span></h2><p class=\"dd-lead\">现实中不知道 P，训练程序又是怎样得到交叉熵损失的？</p>\n        <p>语言模型把一句话分成 <code>x₁,…,xₙ</code>，并在每一步给真实下一个 token 概率 <code>Q(xₜ|x&lt;t)</code>。<b>似然</b>在这里表示模型给整句真实 token 序列分配了多大概率，用来比较模型对已观察文本的解释程度。<b>对数似然</b>把逐步概率的乘法变成对数之和，便于稳定计算；再取负号，就把“概率越大越好”改写成“损失越小越好”。整句负对数似然为：</p>\n        <div class=\"dd-formula\">NLL=−Σₜlog Q(xₜ|x&lt;t)</div>\n        <p>除以 token 数 n，得到这条序列的平均 token 损失；再对训练批次求平均，就是常见的经验交叉熵。它用有限样本近似未知的真实分布 P，而不是直接知道 P。</p>\n        <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>量</th><th>怎样得到</th><th>能否直接观察</th></tr></thead><tbody>\n        <tr><td>总体交叉熵 H(P,Q)</td><td>对未知真实分布 P 取期望</td><td>通常不能精确观察</td></tr>\n        <tr><td>训练损失</td><td>训练样本上的平均负对数概率</td><td>可以计算，但可能过拟合</td></tr>\n        <tr><td>验证/测试损失</td><td>未参与参数更新的样本平均</td><td>用于估计新数据表现，仍有抽样误差</td></tr>\n        </tbody></table></div>\n        <p>因此“训练损失下降”只说明模型更适合当前训练样本。要判断真实预测是否改善，还需独立验证集、分布切片以及事实性、推理、安全等任务指标。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">边界</span></h2><p class=\"dd-lead\">信息论提供概率与编码的尺子，但不会替你定义语义、真实性和价值。</p>\n        <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody>\n        <tr><td>P 是训练集里直接可见的真理</td><td>P 是未知的数据生成分布；样本频率只是估计，还可能受采样偏差影响</td></tr>\n        <tr><td>交叉熵就是两个分布各算一次熵</td><td>事件频率来自 P，单次损失来自 Q，公式是 <code>−ΣPlog₂Q</code></td></tr>\n        <tr><td>KL 是两个概率向量的普通距离</td><td>KL 是有方向的平均对数代价，不对称且不满足三角不等式</td></tr>\n        <tr><td>PPL=20 表示模型只考虑 20 个 token</td><td>它只表示与 20 个等概率候选相当的平均不确定性</td></tr>\n        <tr><td>PPL 下降说明回答更真实、更聪明</td><td>它只测实际 token 的平均预测概率，其他能力需要独立评测</td></tr>\n        </tbody></table></div>\n        <div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>学习位置</th><th>怎样处理</th></tr></thead><tbody>\n        <tr><td>进入本页前</td><td>只需会读概率和加权平均；本页已补充对数、期望、P 与 Q</td></tr>\n        <tr><td><b>本页核心</b></td><td>自信息 → 熵 → 交叉熵 → KL → 困惑度</td></tr>\n        <tr><td>后续正式展开</td><td>1.2 损失函数、1.3 梯度下降、2.8 Token 与分词</td></tr>\n        <tr><td>工程延伸</td><td>预训练、概率校准、采样参数、模型评测与分布漂移</td></tr>\n        </tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把五个量连成一条推导链<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">不要孤立背公式：每一个新量都在回答上一步尚未回答的问题。</p><ol class=\"dd-chain\"><li>事件 x 按真实分布 P 出现，模型用分布 Q 给出预测</li><li>−log₂P(x) 衡量事件在真实分布下的自信息</li><li>按 P 平均 −log₂P(x)，得到真实分布自身的熵 H(P)</li><li>按 P 平均模型损失 −log₂Q(x)，得到交叉熵 H(P,Q)</li><li>交叉熵减去熵，得到模型失配的额外代价 KL(P∥Q)</li><li>把平均 token 交叉熵指数化，得到熵等效分支数 PPL</li><li>最后用独立任务指标检查概率拟合之外的事实性、推理、安全与价值</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">这些问题从符号辨认、数值计算逐步走向边界判断；答案必须说明推理过程。</p><div class=\"dd-quiz\"><ol><li>给定 P(雨)=0.25，计算“今天下雨”的自信息，并说明单位。</li><li>给定 P=(0.5,0.5)，计算 H(P)；如果改成 P=(1,0)，熵怎样变化，为什么？</li><li>在交叉熵 H(P,Q)=−ΣP(x)log₂Q(x) 中，为什么外面的权重是 P(x)，对数里面却是 Q(x)？</li><li>怎样从 H(P,Q) 和 H(P) 推出 KL(P∥Q)？这个差值表示什么？</li><li>为什么欧氏距离不能替代 KL 来表达编码代价？</li><li>假设平均损失为 3 bit/token，计算困惑度，并解释它不代表什么。</li><li>训练交叉熵持续下降，但验证交叉熵开始上升。能否断言真实分布上的 KL 仍在下降？为什么？</li><li>两个语言模型使用不同 tokenizer，模型 A 的 PPL=12、模型 B 的 PPL=15。能否直接断言 A 更好？应怎样比较？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>I(雨)=−log₂0.25=2 bit。因为本页使用以 2 为底的对数，所以单位是 bit。</li><li>前者 H(P)=−0.5log₂0.5−0.5log₂0.5=1 bit；后者 H(P)=0，因为结果已经确定。按约定 0log0 的极限值记为 0。</li><li>P 决定真实事件出现的长期频率，所以负责平均权重；Q 决定模型给已发生事件多少概率，所以 −log₂Q(x) 是模型的单次损失或理想码长。</li><li>相减可得 ΣP(x)[log₂P(x)−log₂Q(x)]=ΣP(x)log₂[P(x)/Q(x)]。它表示数据按 P 产生却使用 Q 预测或编码时，相比使用 P 平均多付出的 bit 数。</li><li>欧氏距离只测概率坐标的几何差且是对称的；KL 测按 P 加权的概率比例和额外对数损失。尤其当 P(x)>0、Q(x)=0 时，欧氏距离仍有限而正向 KL 为正无穷。</li><li>PPL=2³=8。它表示与每步 8 个等概率候选相当的平均不确定性，不表示词表只有 8 个 token，也不证明模型事实性、推理或安全表现良好。</li><li>不能。训练损失是训练样本上的经验平均，可能因过拟合继续下降；验证损失上升反而提示对未见数据的概率预测变差。真实 P 未知，只能通过独立样本近似评估。</li><li>不能。token 单位和序列长度不同会改变 token 级交叉熵与 PPL。应统一 tokenizer、文本、上下文截断和加权口径，或报告共同语料上的 bits-per-byte/character，再结合任务指标比较。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://people.math.harvard.edu/~ctm/home/text/others/shannon/entropy/entropy.pdf\" target=\"_blank\" rel=\"noopener\">A Mathematical Theory of Communication</a>：用于核对自信息、熵、对数底数与无损编码的基本解释</li><li><a href=\"https://www.deeplearningbook.org/contents/prob.html\" target=\"_blank\" rel=\"noopener\">Deep Learning — Probability and Information Theory</a>：用于核对交叉熵、KL、非对称性及机器学习中的概率解释</li><li><a href=\"https://web.stanford.edu/class/stats311/OldSyllabi/full_notes.pdf\" target=\"_blank\" rel=\"noopener\">Stanford STATS 311: Information Theory and Statistics</a>：用于核对熵、KL 和编码观点的正式定义与性质</li></ul><div class=\"dd-src-date\">访问日期：2026-07-25</div></div>"};
